  this.sphere(.33,light,0,1.57,.3,g,[1.15,.72,.68]);for(const x of [-.23,.23]){const mask=this.sphere(.22,dark,x,1.72,.32,g,[1.15,.64,.44]);mask.rotation.z=x<0?-.2:.2;this.sphere(.075,'#d3b979',x,1.73,.4,g,[.8,1,.45]);this.sphere(.041,'#090f0b',x,1.735,.435,g,[.85,1,.45]);this.sphere(.017,'#ffffff',x-.014,1.755,.449,g);}
  this.sphere(.15,light,0,1.54,.51,g,[1.4,.72,.6]);this.sphere(.095,dark,0,1.6,.55,g,[1,.65,.65]);this.tube([[-.09,1.49,.52],[0,1.47,.55],[.1,1.51,.5]],.014,'#383d35',g);
  this.leftArm=this.sphere(.18,jacket,-.47,1.03,.12,g,[.83,1.6,.83]);this.leftArm.rotation.z=-.4;this.rightArm=this.sphere(.18,jacket,.47,1.1,.16,g,[.83,1.6,.83]);this.rightArm.rotation.z=.5;this.sphere(.15,dark,-.56,.81,.2,g);this.sphere(.15,dark,.55,.9,.29,g);
  const chain=this.mesh(new THREE.TorusGeometry(.25,.022,8,32,Math.PI*1.35),this.material('#c9ae64',.2,.8),0,1.27,.35,g);chain.rotation.z=.45;
  this.tail=new THREE.Group();g.add(this.tail);for(let i=0;i<9;i++){const t=i/8;this.sphere(.2+(1-t)*.08,i%2===0?dark:grey,.1+t*.8,.7-t*.28,-.23-t*.69,this.tail,[1,.95,1.1]);}
